{"command":"cat package.json; cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

function diff(base, side) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
    }
  }
  const changes = []
  let i = 0, j = 0, cur = null
  const flush = () => { if (cur) { changes.push(cur); cur = null } }
  while (i < n || j < m) {
    if (i < n && j < m && base[i] === side[j]) { flush(); i++; j++; continue }
    if (!cur) cur = { bs: i, be: i, ss: j, se: j }
    if (j >= m || (i < n && L[i + 1][j] >= L[i][j + 1])) { i++; cur.be = i } else { j++; cur.se = j }
  }
  flush()
  return changes
}

const mode = process.argv.slice(2)
if (mode.length !== 1 || !['merge', 'merge2', 'regions'].includes(mode[0])) fail('usage: cli.js merge|merge2|regions')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const docs = [[]]
for (const l of lines) { if (l === '%%%') docs.push([]); else docs[docs.length - 1].push(l) }
if (docs.length !== 3) fail('expected three parts separated by %%%')
const [mine, base, theirs] = docs

const all = [
  ...diff(base, mine).map(c => ({ ...c, who: 0 })),
  ...diff(base, theirs).map(c => ({ ...c, who: 1 })),
]
all.sort((a, b) => a.bs - b.bs || a.who - b.who)

const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])
const out = []
let conflict = false
let pos = 0
const emitStable = to => {
  if (to > pos) {
    const s = base.slice(pos, to)
    if (mode[0] === 'regions') out.push(`stable ${s.length}`); else out.push(...s)
  }
}
const sides = [mine, theirs]
let k = 0
while (k < all.length) {
  const group = [all[k++]]
  const rs = group[0].bs
  let re = group[0].be
  while (k < all.length && all[k].bs <= re) { re = Math.max(re, all[k].be); group.push(all[k++]) }
  emitStable(rs)
  pos = re
  const rep = [0, 1].map(w => {
    const cs = group.filter(c => c.who === w)
    if (!cs.length) return base.slice(rs, re)
    const first = cs.reduce((a, c) => (c.bs < a.bs ? c : a))
    const s = Math.min(...cs.map(c => c.ss)) - (first.bs - rs)
    const last = cs.reduce((a, c) => (c.be > a.be ? c : a))
    const e = Math.max(...cs.map(c => c.se)) + (re - last.be)
    return sides[w].slice(s, e)
  })
  const baseSeg = base.slice(rs, re)
  const [m, t] = rep
  const reg = mode[0] === 'regions'
  let res, label
  if (group.length === 1) { label = group[0].who === 0 ? 'mine' : 'theirs'; res = rep[group[0].who] }
  else if (eq(m, t)) { label = 'both'; res = m }
  else if (eq(m, baseSeg)) { label = 'theirs'; res = t }
  else if (eq(t, baseSeg)) { label = 'mine'; res = m }
  else label = 'conflict'
  if (label === 'conflict') {
    conflict = true
    if (reg) out.push(`conflict mine=${m.length} base=${baseSeg.length} theirs=${t.length}`)
    else {
      out.push('<<<<<<< mine', ...m)
      if (mode[0] === 'merge') out.push('||||||| base', ...baseSeg)
      out.push('=======', ...t, '>>>>>>> theirs')
    }
  } else if (reg) out.push(`${label} ${res.length}`)
  else out.push(...res)
}
emitStable(base.length)
process.stdout.write(out.map(l => l + '\n').join(''))
process.exit(conflict ? 1 : 0)
EOF
