{"command":"cat package.json; cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'
import { parseDocument, ParseError } from './parser.js'
import { toJson, toKeys } from './output.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'json' && mode !== 'keys') {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
const input = readFileSync(0, 'utf8')
let root
try {
  root = parseDocument(input)
} catch (e) {
  if (e instanceof ParseError) {
    process.stderr.write(`error: line ${e.line}: ${e.message}\n`)
    process.exit(2)
  }
  throw e
}
process.stdout.write(mode === 'json' ? toJson(root) : toKeys(root))
EOF
cat > src/output.js <<'EOF'
function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sortedKeys = (m) => [...m.keys()].sort(cmp)

function ser(n, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (n.t === 'table') {
    if (n.map.size === 0) return '{}'
    const parts = sortedKeys(n.map).map((k) => `${pad}${JSON.stringify(k)}: ${ser(n.map.get(k), ind + 1)}`)
    return `{\n${parts.join(',\n')}\n${end}}`
  }
  if (n.t === 'array') {
    if (n.items.length === 0) return '[]'
    return `[\n${n.items.map((i) => pad + ser(i, ind + 1)).join(',\n')}\n${end}]`
  }
  return JSON.stringify(n.v)
}

export const toJson = (root) => ser(root, 0) + '\n'

export function toKeys(root) {
  const out = []
  const walk = (n, path) => {
    if (n.t === 'table') {
      for (const k of sortedKeys(n.map)) visit(n.map.get(k), path === null ? k : `${path}.${k}`)
    } else if (n.t === 'array') {
      n.items.forEach((it, i) => visit(it, `${path}[${i}]`))
    }
  }
  const visit = (n, p) => {
    out.push(`${p} ${n.t}`)
    walk(n, p)
  }
  walk(root, null)
  return out.map((l) => l + '\n').join('')
}
EOF
cat > src/parser.js <<'EOF'
export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

const table = () => ({ t: 'table', map: new Map(), header: false })
const BARE = /[A-Za-z0-9_-]/
const isWs = (c) => c === ' ' || c === '\t'
const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = table()
  let current = root
  let curPath = []
  for (let i = 0; i < lines.length; i++) {
    const s = lines[i]
    const fail = (m) => {
      throw new ParseError(m, i + 1)
    }
    let p = 0
    const ws = () => {
      while (p < s.length && isWs(s[p])) p++
    }
    const atEnd = () => p >= s.length || s[p] === '#' || s[p] === ';'

    const parseString = () => {
      const q = s[p++]
      let out = ''
      if (q === "'") {
        while (p < s.length && s[p] !== "'") out += s[p++]
        if (p >= s.length) fail('unterminated string')
        p++
        return out
      }
      for (;;) {
        if (p >= s.length) fail('unterminated string')
        const c = s[p++]
        if (c === '"') return out
        if (c !== '\\') {
          out += c
          continue
        }
        if (p >= s.length) fail('unterminated string')
        const e = s[p++]
        const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (e in map) out += map[e]
        else if (e === 'u') {
          const h = s.slice(p, p + 4)
          if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          p += 4
        } else fail(`invalid escape \\${e}`)
      }
    }

    const parseName = () => {
      if (s[p] === '"' || s[p] === "'") return parseString()
      const st = p
      while (p < s.length && BARE.test(s[p])) p++
      if (p === st) fail('expected a name')
      return s.slice(st, p)
    }
    const parseDotted = () => {
      ws()
      const names = [parseName()]
      for (;;) {
        ws()
        if (s[p] !== '.') return names
        p++
        ws()
        names.push(parseName())
      }
    }

    // walk through names (all but those left over), creating tables
    const walk = (base, basePath, names) => {
      let t = base
      const path = [...basePath]
      for (const n of names) {
        path.push(n)
        let nx = t.map.get(n)
        if (!nx) {
          nx = table()
          t.map.set(n, nx)
        } else if (nx.t === 'array' && nx.aot) nx = nx.items[nx.items.length - 1]
        else if (nx.t !== 'table') fail(`${path.join('.')} is not a table`)
        t = nx
      }
      return [t, path]
    }

    const assign = (base, basePath, names, value) => {
      const [t, path] = walk(base, basePath, names.slice(0, -1))
      const k = names[names.length - 1]
      path.push(k)
      if (t.map.has(k)) fail(`key ${path.join('.')} is defined twice`)
      t.map.set(k, value)
    }

    const parseValue = (path) => {
      ws()
      if (atEnd() || s[p] === ',' || s[p] === ']' || s[p] === '}') fail('expected a value')
      const c = s[p]
      if (c === '"' || c === "'") return { t: 'string', v: parseString() }
      if (c === '[') {
        p++
        const arr = { t: 'array', items: [], aot: false }
        for (;;) {
          ws()
          if (atEnd()) fail('unterminated array')
          if (s[p] === ']') {
            p++
            return arr
          }
          arr.items.push(parseValue([...path.slice(0, -1), `${path[path.length - 1]}[${arr.items.length}]`]))
          ws()
          if (s[p] === ',') {
            p++
            continue
          }
          if (s[p] === ']') {
            p++
            return arr
          }
          if (atEnd()) fail('unterminated array')
          fail('trailing text after a value')
        }
      }
      if (c === '{') {
        p++
        const tb = table()
        ws()
        if (atEnd()) fail('unterminated inline table')
        if (s[p] === '}') {
          p++
          return tb
        }
        for (;;) {
          const names = parseDotted()
          if (s[p] !== '=') fail('expected = in an inline table')
          p++
          const v = parseValue([...path, ...names])
          assign(tb, path, names, v)
          ws()
          if (s[p] === ',') {
            p++
            ws()
            if (atEnd()) fail('unterminated inline table')
            continue
          }
          if (s[p] === '}') {
            p++
            return tb
          }
          if (atEnd()) fail('unterminated inline table')
          fail('trailing text after a value')
        }
      }
      const st = p
      while (p < s.length && !isWs(s[p]) && !',]};'.includes(s[p])) p++
      const w = s.slice(st, p)
      if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
      if (INT.test(w)) return { t: 'integer', v: Number(w.replace(/_/g, '')) }
      if (FLOAT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
      return fail(`invalid value ${w}`)
    }

    ws()
    if (atEnd()) continue
    if (s[p] === '[') {
      const dbl = s[p + 1] === '['
      p += dbl ? 2 : 1
      const names = parseDotted()
      ws()
      const close = dbl ? ']]' : ']'
