if (names === null) fail('error: no candidates')

const total = ballots.reduce((s, b) => s + b[0], 0n)
const cont = new Set(names)
const history = []
const out = []
let winner = null
let count = 0
for (;;) {
  count++
  const votes = new Map([...cont].map((c) => [c, 0n]))
  let active = 0n
  for (const [k, list] of ballots) {
    const c = list.find((x) => cont.has(x))
    if (c !== undefined) { votes.set(c, votes.get(c) + k); active += k }
  }
  history.push(votes)
  const order = [...cont].sort((a, b) => (votes.get(a) > votes.get(b) ? -1 : votes.get(a) < votes.get(b) ? 1 : a < b ? -1 : a > b ? 1 : 0))
  out.push(`round ${count}: ${order.map((c) => `${c}=${votes.get(c)}`).join(' ')} exhausted=${total - active}`)
  if (active === 0n) break
  const w = order.find((c) => votes.get(c) * 2n > active)
  if (w !== undefined) { winner = w; break }
  let cand = [...cont]
  let min = cand.reduce((m, c) => (votes.get(c) < m ? votes.get(c) : m), votes.get(cand[0]))
  cand = cand.filter((c) => votes.get(c) === min)
  while (cand.length > 1) {
    let split = false
    for (const h of history) {
      const vs = cand.map((c) => h.get(c))
      const m = vs.reduce((a, b) => (a < b ? a : b))
      if (vs.some((v) => v !== m)) {
        cand = cand.filter((c) => h.get(c) === m)
        split = true
        break
      }
    }
    if (!split) break
  }
  const elim = cand.reduce((a, b) => (a > b ? a : b))
  cont.delete(elim)
  out.push(`eliminated ${elim}`)
}
const end = winner === null ? 'no winner' : `winner ${winner}`
if (mode === 'rounds') process.stdout.write(out.join('\n') + '\n' + end + '\n')
else process.stdout.write(`rounds ${count}\n${end}\n`)
