}
for (const [name, ...ds] of depLines) for (const d of ds) deps.get(name).add(d)

const names = [...cost.keys()].sort()
const sortedDeps = new Map(names.map((k) => [k, [...deps.get(k)].sort()]))

// cycle detection
{
  const state = new Map()
  const stack = []
  const dfs = (u) => {
    state.set(u, 1)
