import { readFileSync } from 'node:fs'

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }
const UNRESERVED = /^[A-Za-z0-9\-._~]$/

class Fail extends Error {}

function parse(s) {
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#(.*))?$/s.exec(s)
  return { scheme: m[1], authority: m[2], path: m[3], query: m[4], fragment: m[5] }
}

function splitAuthority(a) {
  let userinfo, rest = a
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); rest = a.slice(at + 1) }
  const colon = rest.indexOf(':', rest.lastIndexOf(']') + 1)
  let host = rest, port
  if (colon >= 0) { host = rest.slice(0, colon); port = rest.slice(colon + 1) }
  return { userinfo, host, port }
}

function pct(s, label) {
  if (/%(?![0-9A-Fa-f]{2})/.test(s)) throw new Fail(`the ${label} has a truncated percent-encoding`)
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(c) ? c : '%' + h.toUpperCase()
  })
}

function lowerHost(h) {
  return h.replace(/%[0-9A-F]{2}|[A-Z]/g, (t) => (t[0] === '%' ? t : t.toLowerCase()))
}

function removeDots(path) {
  let input = path, out = ''
  while (input.length) {
    if (input.startsWith('../')) input = input.slice(3)
    else if (input.startsWith('./')) input = input.slice(2)
    else if (input.startsWith('/./')) input = input.slice(2)
    else if (input === '/.') input = '/'
    else if (input.startsWith('/../') || input === '/..') {
      input = input === '/..' ? '/' : input.slice(3)
      out = out.slice(0, out.lastIndexOf('/') < 0 ? 0 : out.lastIndexOf('/'))
    } else if (input === '.' || input === '..') input = ''
    else {
      const i = input.indexOf('/', 1)
      const seg = i < 0 ? input : input.slice(0, i)
      out += seg
      input = input.slice(seg.length)
    }
  }
  return out
}

function serialize(u) {
  let s = ''
  if (u.scheme !== undefined) s += u.scheme + ':'
  if (u.authority !== undefined) s += '//' + u.authority
  s += u.path
  if (u.query !== undefined) s += '?' + u.query
  if (u.fragment !== undefined) s += '#' + u.fragment
  return s
}

function normalize(u) {
  const scheme = u.scheme === undefined ? undefined : u.scheme.replace(/[A-Z]/g, (c) => c.toLowerCase())
  const path = pct(u.path, 'path')
  let authority
  if (u.authority !== undefined) {
    const a = splitAuthority(u.authority)
    const userinfo = a.userinfo === undefined ? undefined : pct(a.userinfo, 'userinfo')
    const host = lowerHost(pct(a.host, 'host'))
    let port = a.port
    if (port === '' || (scheme !== undefined && port === DEFAULT_PORTS[scheme])) port = undefined
    authority = (userinfo === undefined ? '' : userinfo + '@') + host + (port === undefined ? '' : ':' + port)
  }
  const query = u.query === undefined ? undefined : pct(u.query, 'query')
  const fragment = u.fragment === undefined ? undefined : pct(u.fragment, 'fragment')
  let p = removeDots(path)
  if (authority !== undefined && p === '') p = '/'
  return serialize({ scheme, authority, path: p, query, fragment })
}

