    else {
      const i = base.path.lastIndexOf('/')
      path = i < 0 ? ref.path : base.path.slice(0, i + 1) + ref.path
    }
    t.scheme = base.scheme; t.authority = base.authority
    t.path = removeDots(path); t.query = ref.query; t.fragment = ref.fragment
  }
  return t
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const out = []
  for (let n = 1; n <= lines.length; n++) {
    const line = lines[n - 1]
    try {
      if (args[0] === 'normalize') out.push(normalize(parse(line)))
      else {
        const sp = line.indexOf(' ')
        if (sp < 0) throw new Fail('expected a base and a reference')
        const base = parse(line.slice(0, sp))
        if (base.scheme === undefined) throw new Fail('the base has no scheme')
        out.push(normalize(resolve(base, parse(line.slice(sp + 1)))))
      }
    } catch (e) {
      if (!(e instanceof Fail)) throw e
      process.stderr.write(`error: line ${n}: ${e.message}\n`)
      process.exit(2)
    }
  }
  if (out.length) process.stdout.write(out.join('\n') + '\n')
}

