export class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.'.split(''))
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdChar = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

export function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  let i = 0
  let line = 1
  let col = 1
  const toks = []

  const adv = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const fail = (l, c, r) => { throw new ScanError(l, c, r) }

  // consume a run of digits (per pred) with single underscores between digits
  const run = (pred) => {
    let s = ''
    while (i < n) {
      if (pred(cs[i])) s += adv()
      else if (cs[i] === '_' && s !== '' && pred(cs[i - 1]) && pred(cs[i + 1])) s += adv()
      else break
    }
    return s
  }

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      const sl = line, sc = col
      adv(); adv()
      let depth = 1
      while (depth > 0) {
        if (i >= n) fail(sl, sc, 'unterminated block comment')
        if (cs[i] === '*' && cs[i + 1] === '/') { adv(); adv(); depth-- }
        else if (cs[i] === '/' && cs[i + 1] === '*') { adv(); adv(); depth++ }
        else adv()
      }
      continue
    }
    const sl = line, sc = col
    const push = (kind, body) => toks.push({ line: sl, col: sc, kind, body })

    if (c === 'r' && cs[i + 1] === '"') {
      adv(); adv()
      let v = ''
      while (true) {
        if (i >= n) fail(sl, sc, 'unterminated string')
        const d = adv()
        if (d === '"') break
        v += d
      }
      push('rawstring', JSON.stringify(v))
      continue
    }
    if (isIdStart(c)) {
      let s = ''
      while (i < n && isIdChar(cs[i])) s += adv()
      push(KEYWORDS.has(s) ? 'keyword' : 'ident', s)
      continue
    }
    if (isDigit(c)) {
      let s = ''
      let ok = true
      const p = cs[i + 1]
      const pred = c === '0' && (p === 'x' || p === 'X') ? isHex
        : c === '0' && (p === 'b' || p === 'B') ? isBin
        : c === '0' && (p === 'o' || p === 'O') ? isOct : null
      if (pred) {
        s += adv() + adv()
        const r = run(pred)
        s += r
        if (r === '') ok = false
      } else {
        s += run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { s += adv(); s += run(isDigit) }
        if (cs[i] === 'e' || cs[i] === 'E') {
          const a = cs[i + 1], b = cs[i + 2]
          if (isDigit(a) || ((a === '+' || a === '-') && isDigit(b))) {
            s += adv()
            if (!isDigit(cs[i])) s += adv()
            s += run(isDigit)
          }
        }
      }
      if (i < n && isIdChar(cs[i])) {
        ok = false
        while (i < n && isIdChar(cs[i])) s += adv()
      }
      if (!ok) fail(sl, sc, `invalid number ${s}`)
      push('number', s)
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      while (true) {
        if (i >= n) fail(sl, sc, 'unterminated string')
        if (cs[i] === '\n') fail(line, col, 'newline in string')
        const bl = line, bc = col
        const d = adv()
        if (d === '"') break
        if (d !== '\\') { v += d; continue }
        if (i >= n) fail(sl, sc, 'unterminated string')
        const e = adv()
        const bad = () => fail(bl, bc, `invalid escape \\${e}`)
        if (e === 'n') v += '\n'
        else if (e === 't') v += '\t'
        else if (e === 'r') v += '\r'
        else if (e === '\\') v += '\\'
        else if (e === '"') v += '"'
        else if (e === '0') v += '\0'
        else if (e === 'x') {
          let h = ''
          for (let k = 0; k < 2; k++) {
            if (i >= n) fail(sl, sc, 'unterminated string')
            if (!isHex(cs[i])) bad()
            h += adv()
          }
          v += String.fromCodePoint(parseInt(h, 16))
        } else if (e === 'u') {
          if (i >= n) fail(sl, sc, 'unterminated string')
          if (cs[i] !== '{') bad()
          adv()
          let h = ''
          while (i < n && isHex(cs[i])) h += adv()
          if (i >= n) fail(sl, sc, 'unterminated string')
          if (cs[i] !== '}' || h === '') bad()
          adv()
          const cp = parseInt(h, 16)
          if (cp > 0x10ffff) bad()
          v += String.fromCodePoint(cp)
        } else bad()
      }
      push('string', JSON.stringify(v))
      continue
    }
    const two = c + (cs[i + 1] ?? '')
    if (PUNCT2.has(two)) { adv(); adv(); push('punct', two); continue }
    if (PUNCT1.has(c)) { adv(); push('punct', c); continue }
    fail(sl, sc, `unexpected character ${c}`)
  }
  return toks
}
