{"file_path":"src/sheet.js","content":"import { parseAddress } from './address.js'

function fail(msg) {
  const e = new Error(msg)
  e.sheetError = true
  return e
}

/** Parses the sheet text into cells sorted by column then row. */
export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const seen = new Set()
  const cells = []
  lines.forEach((raw, i) => {
    const line = raw.replace(/^[ \t]+/, '')
    if (line === '' || line[0] === '#') return
    const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(line)
    const addr = m[1].toUpperCase()
    const content = m[2]
    const p = parseAddress(addr)
    if (!p) throw fail(`error: line ${i + 1}: invalid cell address ${addr}`)
    if (seen.has(p.key)) throw fail(`error: line ${i + 1}: cell ${addr} is declared twice`)
    seen.add(p.key)
    cells.push({ addr, key: p.key, col: p.col, row: p.row, content })
  })
  cells.sort((a, b) => a.col - b.col || a.row - b.row)
  return cells
}
"}

{"file_path":"src/address.js","content":"/** Column index: A..Z = 1..26, AA..ZZ = 27..702. */
export function colIndex(letters) {
  if (letters.length === 1) return letters.charCodeAt(0) - 64
  return 26 + (letters.charCodeAt(0) - 65) * 26 + (letters.charCodeAt(1) - 64)
}

export function keyOf(col, row) {
  return col * 1000 + row
}

/** Returns {col,row,key} for an in-range address (any case), else null. */
export function parseAddress(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const col = colIndex(m[1].toUpperCase())
  return { col, row, key: keyOf(col, row) }
}
"}

{"file_path":"src/formula.js","content":"import { parseAddress } from './address.js'

const CMP = ['=', '<>', '<', '<=', '>', '>=']

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) })
      i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ t: 'word', v: m[0].toUpperCase() })
      i += m[0].length
    } else if (s.startsWith('<>', i) || s.startsWith('<=', i) || s.startsWith('>=', i)) {
      toks.push({ t: 'op', v: s.slice(i, i + 2) })
      i += 2
    } else if ('^*/+-=<>(),:'.includes(c)) {
      toks.push({ t: 'op', v: c })
      i++
    } else return null
  }
  return toks
}

class Bad extends Error {}

/** Returns a syntax tree or null when the grammar rejects the body. */
export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const peekOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v

  function comparison() {
    let l = additive()
    while (p < toks.length && toks[p].t === 'op' && CMP.includes(toks[p].v)) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: additive() }
    }
    return l
  }
  function additive() {
    let l = term()
    while (peekOp('+') || peekOp('-')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: term() }
    }
    return l
  }
  function term() {
    let l = power()
    while (peekOp('*') || peekOp('/')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: power() }
    }
    return l
  }
  function power() {
    const l = unary()
    if (peekOp('^')) {
      p++
      return { k: 'bin', op: '^', l, r: power() }
    }
    return l
  }
  function unary() {
    if (peekOp('-') || peekOp('+')) {
      const op = toks[p++].v
      return { k: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const t = toks[p]
    if (!t) throw new Bad()
    if (t.t === 'num') { p++; return { k: 'num', v: t.v } }
    if (t.t === 'op') {
      if (t.v !== '(') throw new Bad()
      p++
      const e = comparison()
      if (!peekOp(')')) throw new Bad()
      p++
      return { k: 'paren', e }
    }
    p++
    if (peekOp('(')) {
      p++
      const args = []
      if (peekOp(')')) { p++ } else {
        for (;;) {
          args.push(comparison())
          if (peekOp(',')) { p++; continue }
          if (peekOp(')')) { p++; break }
          throw new Bad()
        }
      }
      return { k: 'call', name: t.v, args }
    }
    if (peekOp(':')) {
      p++
      const u = toks[p]
      if (!u || u.t !== 'word') throw new Bad()
      p++
      if (peekOp('(')) throw new Bad()
      return { k: 'range', a: parseAddress(t.v), b: parseAddress(u.v) }
    }
    if (t.v === 'TRUE') return { k: 'bool', v: true }
    if (t.v === 'FALSE') return { k: 'bool', v: false }
    return { k: 'ref', a: parseAddress(t.v) }
  }

  try {
    const tree = comparison()
    if (p !== toks.length) return null
    return tree
  } catch (e) {
    if (e instanceof Bad) return null
    throw e
  }
}

/** Distinct in-range addresses named by the tree, as sorted strings. */
export function collectDeps(tree) {
  const set = new Map()
  const add = (col, row) => set.set(col * 1000 + row, { col, row })
  ;(function walk(n) {
    switch (n.k) {
      case 'ref': if (n.a) add(n.a.col, n.a.row); break
      case 'range':
        if (n.a && n.b) {
          for (let c = Math.min(n.a.col, n.b.col); c <= Math.max(n.a.col, n.b.col); c++)
            for (let r = Math.min(n.a.row, n.b.row); r <= Math.max(n.a.row, n.b.row); r++) add(c, r)
        }
        break
      case 'bin': walk(n.l); walk(n.r); break
      case 'un': case 'paren': walk(n.e); break
      case 'call': n.args.forEach(walk); break
    }
  })(tree)
  return [...set.values()]
    .sort((a, b) => a.col - b.col || a.row - b.row)
    .map(({ col, row }) => colName(col) + row)
}

export function colName(col) {
  if (col <= 26) return String.fromCharCode(64 + col)
  const x = col - 27
  return String.fromCharCode(65 + Math.floor(x / 26), 65 + (x % 26))
}
"}

