  if (typeof v === 'number') return String(Number(v.toPrecision(10)))
  return v
}

function rank(v) {
  return typeof v === 'number' ? 0 : typeof v === 'string' ? 1 : 2
}

function cmpStr(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) if (x[i] !== y[i]) return x[i] < y[i] ? -1 : 1
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
}

function compare(a, b) {
  const ra = rank(a), rb = rank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (ra === 1) return cmpStr(a, b)
  const x = Number(a), y = Number(b)
  return x < y ? -1 : x > y ? 1 : 0
}

function fin(n) {
  return Number.isFinite(n) ? n : E.div
}

/** Converts a non-error value to a number, or #VALUE!. */
function num(v) {
  if (typeof v === 'number') return v
  if (typeof v === 'boolean') return v ? 1 : 0
  return E.value
