const NAME = /^[A-Za-z0-9_-]+$/
const COUNT = /^[1-9][0-9]*$/

function fail(msg) {
  const e = new Error(msg)
  e.election = true
  throw e
}

export function parse(text) {
  const raw = text.split('\n')
  if (raw.length && raw[raw.length - 1] === '') raw.pop()
  let candidates = null
  let seenBallot = false
  const ballots = []
  raw.forEach((line, i) => {
    const n = i + 1
    const t = line.trim()
    if (t === '' || t.startsWith('#')) return
    const w = t.split(/\s+/)
    if (w[0] === 'candidates') {
      if (candidates !== null || seenBallot) fail(`line ${n}: candidates must be declared once, before any ballot`)
      if (w.length < 2) fail(`line ${n}: expected candidates <name>...`)
      const seen = new Set()
      for (const name of w.slice(1)) {
        if (!NAME.test(name)) fail(`line ${n}: invalid candidate name ${name}`)
        if (seen.has(name)) fail(`line ${n}: candidate ${name} is declared twice`)
        seen.add(name)
      }
      candidates = w.slice(1)
    } else if (w[0] === 'ballot') {
      if (candidates === null) fail(`line ${n}: candidates must be declared once, before any ballot`)
      seenBallot = true
      if (w.length < 3) fail(`line ${n}: expected ballot <count> <candidate>...`)
      if (!COUNT.test(w[1])) fail(`line ${n}: count must be a positive integer`)
      const seen = new Set()
      for (const name of w.slice(2)) {
        if (!candidates.includes(name)) fail(`line ${n}: unknown candidate ${name}`)
        if (seen.has(name)) fail(`line ${n}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ n: BigInt(w[1]), prefs: w.slice(2) })
    } else {
      fail(`line ${n}: unknown directive ${w[0]}`)
    }
  })
  if (candidates === null) fail('no candidates')
  return { candidates, ballots }
}

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

export function count({ candidates, ballots }, tally) {
  const continuing = new Set(candidates)
  const history = []
  const lines = []
  let winner = null
  let rounds = 0
  for (;;) {
    rounds++
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    for (const b of ballots) {
      const c = b.prefs.find((p) => continuing.has(p))
      if (c !== undefined) {
        votes.set(c, votes.get(c) + b.n)
        active += b.n
      }
    }
    const total = ballots.reduce((s, b) => s + b.n, 0n)
    history.push(votes)
    const order = [...votes.keys()].sort((a, b) => cmp(votes.get(b), votes.get(a)) || cmp(a, b))
    let line = `round ${rounds}: ` + order.map((c) => `${c}=${votes.get(c)}`).join(' ')
    line += ` exhausted=${total - active}`
    lines.push(line)
    if (active === 0n) break
    const w = order.find((c) => votes.get(c) * 2n > active)
    if (w !== undefined) {
      winner = w
      break
    }
    let tied = [...continuing]
    let min = tied.reduce((m, c) => (votes.get(c) < m ? votes.get(c) : m), votes.get(tied[0]))
    tied = tied.filter((c) => votes.get(c) === min)
    let k = 0
    while (tied.length > 1 && k < history.length) {
      const vs = tied.map((c) => history[k].get(c))
      const m = vs.reduce((a, b) => (b < a ? b : a))
      if (vs.some((v) => v !== m)) {
        tied = tied.filter((c) => history[k].get(c) === m)
        k = 0
      } else k++
    }
    const out = tied.sort(cmp).pop()
    continuing.delete(out)
    lines.push(`eliminated ${out}`)
  }
  return { lines: tally ? [`rounds ${rounds}`] : lines, winner }
}
