cat > src/render.js <<'EOF'
import { Table, ArrayOfTables, List } from './parser.js'

export function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}

const sortedKeys = (t) => [...t.map.keys()].sort(cmp)

function json(node, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (node instanceof Table) {
    const ks = sortedKeys(node)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${json(node.map.get(k), ind + 1)}`).join(',\n') + '\n' + end + '}'
  }
  if (node instanceof ArrayOfTables || node instanceof List) {
    if (!node.items.length) return '[]'
    return '[\n' + node.items.map((v) => pad + json(v, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  if (node.type === 'integer') return BigInt(node.value).toString()
  return JSON.stringify(node.value)
}

export const renderJson = (root) => json(root, 0) + '\n'

function typeOf(n) {
  if (n instanceof Table) return 'table'
  if (n instanceof ArrayOfTables || n instanceof List) return 'array'
  return n.type
}

export function renderKeys(root) {
  const lines = []
  const walk = (node, path) => {
    if (node instanceof Table) {
      for (const k of sortedKeys(node)) visit(node.map.get(k), path === null ? k : path + '.' + k)
    } else if (node instanceof ArrayOfTables || node instanceof List) {
      node.items.forEach((v, i) => visit(v, path + `[${i}]`))
    }
  }
  const visit = (n, p) => {
    lines.push(`${p} ${typeOf(n)}`)
    walk(n, p)
  }
  walk(root, null)
  return lines.map((l) => l + '\n').join('')
}
