      path.push(k)
      let nx = cur.map.get(k)
      if (nx === undefined) {
        nx = new Table()
        cur.map.set(k, nx)
      }
      if (nx instanceof ArrayOfTables) nx = nx.items[nx.items.length - 1]
      if (!(nx instanceof Table)) this.fail(`${path.join('.')} is not a table`)
      cur = nx
    }
