    if (line === '' || line.startsWith('#')) return
    const t = line.split(/\s+/)
    const fail = (m) => {
      throw new ParseError(`line ${i + 1}: ${m}`)
    }
    const int = (field, v, least) => {
      if (!UINT.test(v) || BigInt(v) < BigInt(least)) fail(`${field} must be an integer of at least ${least}`)
      return BigInt(v)
    }
    const decl = () => {
      if (started) fail('declarations must come before the first event')
    }
    const name = (v) => {
      if (!WORD.test(v)) fail(`invalid policy name ${v}`)
      if (policies.has(v)) fail(`policy ${v} is declared twice`)
    }
    switch (t[0]) {
      case 'bucket': {
        if (t.length !== 5) fail('expected bucket <name> <capacity> <refill> <per>')
        decl()
        name(t[1])
        const capacity = int('capacity', t[2], 1)
        const refill = int('refill', t[3], 0)
        const per = int('per', t[4], 1)
        policies.set(t[1], { kind: 'bucket', name: t[1], capacity, refill, per })
        break
      }
      case 'window': {
        if (t.length !== 4) fail('expected window <name> <limit> <span>')
        decl()
        name(t[1])
        const limit = int('limit', t[2], 0)
        const span = int('span', t[3], 1)
        policies.set(t[1], { kind: 'window', name: t[1], limit, span })
        break
      }
      case 'route': {
        if (t.length < 3) fail('expected route <prefix> <policy>...')
        decl()
        if (!WORD.test(t[1])) fail(`invalid route prefix ${t[1]}`)
        if (routes.has(t[1])) fail(`prefix ${t[1]} is routed twice`)
        const list = t.slice(2).map((p) => {
          if (!policies.has(p)) fail(`unknown policy ${p}`)
          return policies.get(p)
        })
        routes.set(t[1], list)
        break
