        if (t.length !== 3) fail('expected event <tick> <key>')
        const tick = int('tick', t[1], 0)
        if (!WORD.test(t[2])) fail(`invalid key ${t[2]}`)
        if (lastTick !== null && tick < lastTick) fail(`tick ${tick} is before tick ${lastTick}`)
        lastTick = tick
        started = true
        events.push({ tick, key: t[2] })
        break
      }
      default:
