for (const w of depLines) for (const x of w.slice(1)) deps.get(w[0]).add(x)

const names = [...cost.keys()].sort()
const dsorted = new Map(names.map((k) => [k, [...deps.get(k)].sort()]))

// cycle detection
{
  const state = new Map()
  const stack = []
  const visit = (u) => {
    state.set(u, 1)
    stack.push(u)
