      let wi = freeAt.findIndex((f) => f <= t)
      if (wi < 0) break
      let best = null
      for (const k of pending) {
        if (!dsorted.get(k).every((d) => done.has(d) && done.get(d) <= t)) continue
        if (best === null || prio.get(k) > prio.get(best) || (prio.get(k) === prio.get(best) && k < best)) best = k
      }
      if (best === null) break
      pending.delete(best)
      const f = t + cost.get(best)
      done.set(best, f)
      freeAt[wi] = f
      ran[wi].push(`${best}@${t}-${f}`)
      makespan = Math.max(makespan, f)
    }
    if (pending.size === 0) break
    let next = Infinity
    for (const f of freeAt) if (f > t && f < next) next = f
    if (next === Infinity) break
    t = next
  }
  ran.forEach((r, i) => {
    out += `worker ${i}:${r.map((x) => ' ' + x).join('')}\n`
  })
  out += `makespan ${makespan}\n`
}
process.stdout.write(out)
EOF
