{"command":"cat > src/cli.js <<'EOF'
#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */
import { readFileSync } from 'node:fs'

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

class Fail extends Error {}

function parse(s) {
  const r = { scheme: undefined, authority: undefined, path: '', query: undefined, fragment: undefined }
  let m = /^([^:/?#]+):/.exec(s)
  if (m) { r.scheme = m[1]; s = s.slice(m[0].length) }
  if (s.startsWith('//')) {
    const e = s.slice(2).search(/[/?#]/)
    if (e < 0) { r.authority = s.slice(2); s = '' } else { r.authority = s.slice(2, 2 + e); s = s.slice(2 + e) }
  }
  const h = s.indexOf('#')
  if (h >= 0) { r.fragment = s.slice(h + 1); s = s.slice(0, h) }
  const q = s.indexOf('?')
  if (q >= 0) { r.query = s.slice(q + 1); s = s.slice(0, q) }
  r.path = s
  return r
}

function splitAuthority(a) {
  let userinfo, rest = a
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); rest = a.slice(at + 1) }
  const from = rest.lastIndexOf(']') + 1
  const c = rest.indexOf(':', from)
  let host = rest, port
  if (c >= 0) { host = rest.slice(0, c); port = rest.slice(c + 1) }
  return { userinfo, host, port }
}

function removeDots(path) {
  let inp = path, out = ''
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, Math.max(out.lastIndexOf('/'), 0))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

const truncated = (s) => /%(?![0-9A-Fa-f]{2})/.test(s)
const UNRESERVED = /[A-Za-z0-9\-._~]/
function normPct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(c) ? c : '%' + h.toUpperCase()
  })
}
const lowerAscii = (s) => s.replace(/[A-Z]+/g, (x) => x.toLowerCase())

function check(t, line) {
  const parts = t.authority === undefined ? {} : splitAuthority(t.authority)
  const list = [['path', t.path], ['userinfo', parts.userinfo], ['host', parts.host], ['query', t.query], ['fragment', t.fragment]]
  for (const [name, v] of list) {
    if (v !== undefined && truncated(v)) throw new Fail(`error: line ${line}: the ${name} has a truncated percent-encoding`)
  }
}

function recompose(t) {
  let s = ''
  if (t.scheme !== undefined) s += t.scheme + ':'
  if (t.authority !== undefined) s += '//' + t.authority
  s += t.path
  if (t.query !== undefined) s += '?' + t.query
  if (t.fragment !== undefined) s += '#' + t.fragment
  return s
}

function normalize(t) {
  const scheme = t.scheme === undefined ? undefined : lowerAscii(t.scheme)
  let authority
  if (t.authority !== undefined) {
    const { userinfo, host, port } = splitAuthority(t.authority)
    authority = ''
    if (userinfo !== undefined) authority += normPct(userinfo) + '@'
    authority += lowerAscii(normPct(host))
    if (port !== undefined && port !== '' && !(scheme !== undefined && DEFAULT_PORTS[scheme] === port)) {
      authority += ':' + normPct(port)
    }
  }
  let path = removeDots(normPct(t.path))
  if (authority !== undefined && path === '') path = '/'
  return recompose({
    scheme,
    authority,
    path,
    query: t.query === undefined ? undefined : normPct(t.query),
    fragment: t.fragment === undefined ? undefined : normPct(t.fragment),
  })
}

function resolve(base, ref) {
  const t = {}
  if (ref.scheme !== undefined) {
    Object.assign(t, ref, { path: removeDots(ref.path) })
  } else if (ref.authority !== undefined) {
    Object.assign(t, ref, { scheme: base.scheme, path: removeDots(ref.path) })
  } else {
    t.scheme = base.scheme
    t.authority = base.authority
    t.fragment = ref.fragment
    if (ref.path === '') {
      t.path = base.path
      t.query = ref.query !== undefined ? ref.query : base.query
    } else {
      t.query = ref.query
      if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
      else {
        let merged
        if (base.authority !== undefined && base.path === '') merged = '/' + ref.path
        else {
          const i = base.path.lastIndexOf('/')
          merged = i < 0 ? ref.path : base.path.slice(0, i + 1) + ref.path
        }
        t.path = removeDots(merged)
      }
    }
  }
  return t
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    throw new Fail('error: usage: cli.js normalize|resolve')
  }
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const out = []
  lines.forEach((rec, idx) => {
    const n = idx + 1
    let t
    if (args[0] === 'normalize') t = parse(rec)
    else {
      const sp = rec.indexOf(' ')
      if (sp < 0) throw new Fail(`error: line ${n}: expected a base and a reference`)
      const base = parse(rec.slice(0, sp))
      if (base.scheme === undefined) throw new Fail(`error: line ${n}: the base has no scheme`)
      t = resolve(base, parse(rec.slice(sp + 1)))
    }
    check(t, n)
    out.push(normalize(t))
  })
  if (out.length) process.stdout.write(out.join('\n') + '\n')
}

try {
  main()
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exit(2)
}
