    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const f = line.split(/\s+/)
    const at = (m) => new Fail(`line ${i + 1}: ${m}`)
    try {
      const d = f[0]
      if (d === 'bucket' || d === 'window' || d === 'route') {
        if (started) throw new Fail('declarations must come before the first event')
      }
      if (d === 'bucket' || d === 'window') {
        const isB = d === 'bucket'
        if (f.length !== (isB ? 5 : 4)) throw new Fail(isB ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
        if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        let p
        if (isB) {
          p = { type: 'bucket', name: f[1], cap: num(f[2], 'capacity', 1), refill: num(f[3], 'refill', 0), per: num(f[4], 'per', 1) }
        } else {
          p = { type: 'window', name: f[1], limit: num(f[2], 'limit', 0), span: num(f[3], 'span', 1) }
        }
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], p)
      } else if (d === 'route') {
        if (f.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (!NAME.test(f[1])) throw new Fail(`invalid route prefix ${f[1]}`)
        if (routes.has(f[1])) throw new Fail(`prefix ${f[1]} is routed twice`)
        for (const n of f.slice(2)) if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
        routes.set(f[1], f.slice(2).map((n) => policies.get(n)))
      } else if (d === 'event') {
        if (f.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = num(f[1], 'tick', 0)
        const key = f[2]
        if (!NAME.test(key)) throw new Fail(`invalid key ${key}`)
        if (last !== null && tick < last) throw new Fail(`tick ${tick} is before tick ${last}`)
        started = true
        last = tick
        let best = null
        for (const pre of routes.keys()) if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
        let refused = null
        if (best !== null) {
