      throw e
    }
  }
  if (mode === 'summary') {
    for (const k of [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))) out.push(`${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}`)
    out.push(`total allowed=${allowed} denied=${denied}`)
  }
  return out.length ? out.join('\n') + '\n' : ''
}

