  if (name === 'COUNT') return vals.filter((v) => typeof v === 'number').length
  const nums = []
  for (const v of vals) {
    const x = num(v)
    if (x instanceof Err) return x
    nums.push(x)
  }
  switch (name) {
    case 'SUM': return fin(nums.reduce((a, b) => a + b, 0))
    case 'MIN': return Math.min(...nums)
    case 'MAX': return Math.max(...nums)
    default: return fin(nums.reduce((a, b) => a + b, 0) / nums.length)
  }
}

function show(v) {
  if (v instanceof Err) return v.t
  if (v instanceof Text) return v.s
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE'
  return String(Number(v.toPrecision(10)))
}

const sorted = [...cells.values()].sort((a, b) => a.addr.col - b.addr.col || a.addr.row - b.addr.row)
let out = ''
for (const c of sorted) {
  const k = key(c.addr)
  if (mode === 'values') out += `${k}=${show(cellValue(c.addr))}\n`
  else {
    const set = new Map()
    const ast = c.content[0] === '=' ? getParsed(k) : null
    if (ast) collectDeps(ast, set)
    const ds = [...set.values()].sort((a, b) => a.col - b.col || a.row - b.row)
    out += `${k}:${ds.map((d) => ' ' + key(d)).join('')}\n`
  }
}
process.stdout.write(out)
